package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRuleFieldOptions;

class FieldVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property field of observed fingerprint rule ")
  void test_field_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> FieldVO.tryFrom("_MESSAGE_"));
    Assertions.assertEquals(ObservedFingerprintRuleFieldOptions.MESSAGE,
        FieldVO.tryFrom("MESSAGE").getField());
    Assertions.assertThrows(ConstraintException.class, () -> FieldVO.tryFrom(null));
    Assertions.assertEquals(ObservedFingerprintRuleFieldOptions.MESSAGE,
        FieldVO.from(ObservedFingerprintRuleFieldOptions.MESSAGE).getField());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> FieldVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedFingerprintRuleFieldOptions.MESSAGE + "]",
        FieldVO.from(ObservedFingerprintRuleFieldOptions.MESSAGE).toString());
  }
}
